#!/bin/sh
#
# Generated by the sh backend. Non-POSIX constructs used:
# - 'local': variable scoping (POSIX sh lacks local, but dash/bash/zsh support it)
# - Array emulation (name_0, name_len): arrays are not POSIX
# - '(( ))' arithmetic: required for integer comparison in conditions
# - 'grep -P' helper: PCRE not in POSIX, checked at runtime
#
echo Warmup 1
echo apple | perl -ne 'print "Fruit: $_\n"'
echo '=== Example 1: Simple Perl one-liner ==='
perl -e 'print "Hello from Perl!\n"'
printf '%b\n' '\n=== Example 2: Perl with arguments ==='
perl -e 'foreach $arg (@ARGV) { print "Argument: $arg\n" }' first second third
printf '%b\n' '\n=== Example 3: Perl processing shell variables ==='
SHELL_VAR='Hello World'
perl -e 'print "Shell variable: $ENV{SHELL_VAR}\n"'
export SHELL_VAR
perl -e 'print "Shell variable: $ENV{SHELL_VAR}\n"'
printf '%b\n' '\n=== Example 4: Perl reading from pipeline ==='
printf '%b\n' 'apple\nbanana\ncherry' | perl -ne 'chomp; print "Fruit: $_\n"'
printf '%b\n' '\n=== Example 5: Perl script with here document ==='
perl <<'EOF'
use strict;
use warnings;

my @numbers = (1, 2, 3, 4, 5);
my $sum = 0;

foreach my $num (@numbers) {
    $sum += $num;
    print "Added $num, sum is now $sum\n";
}

print "Final sum: $sum\n";
EOF

